export function sourceById(id) { return managedSources.find(source => source.id === id); }
export function normalizeSourceContent(content) { return String(content).replace(/\s+/g, ' ').trim(); }

export function initialRegistry() {
  return [
    { id: 'overview', acceptedSnapshot: sourceById('overview').currentContent, kbMappings: ['hosting', 'api'], objectives: ['App Service hosting capabilities'], lastChecked: 'Not checked in this run', status: 'Active' },
    { id: 'certificates', acceptedSnapshot: 'Free App Service managed certificates renew automatically.', kbMappings: ['renewal-basics'], objectives: [coverageObjective], lastChecked: 'Not checked in this run', status: 'Active' },
  ];
}

export function gapIsCovered(gapId, registry) {
  const gap = knowledgeGaps.find(item => item.id === gapId);
  const record = registry.find(item => item.id === gap?.sourceId);
  return !!record && normalizeSourceContent(record.acceptedSnapshot) === normalizeSourceContent(sourceById(record.id).currentContent);
}

export function commitSources(registry, sourceIds) {
  return sourceIds.reduce((records, id) => {
    const source = sourceById(id);
    if (!source) return records;
    const existing = records.find(item => item.id === id);
    const accepted = { id, acceptedSnapshot: source.currentContent, kbMappings: source.chunks.map(chunk => chunk.id), objectives: [...new Set([...(existing?.objectives || []), source.objective])], lastChecked: existing?.lastChecked || 'Awaiting first check', status: 'Active' };
    return [...records.filter(item => item.id !== id), accepted];
  }, [...registry]);
}

export function compareSource(record) {
  const source = sourceById(record.id);
  return { changed: normalizeSourceContent(record.acceptedSnapshot) !== normalizeSourceContent(source.currentContent), accepted: record.acceptedSnapshot, retrieved: source.currentContent };
}

export function assistantAnswer(question, registry) {
  if (question === 'hosting') return 'Yes. Azure App Service supports Python web applications alongside several other application stacks.';
  if (question === 'api') return 'Yes. App Service can host REST APIs as well as web applications. The existing hosting documentation already covers this use.';
  if (question === 'renewal' && gapIsCovered('renewal', registry)) return 'Start with the certificate type. Free managed certificates renew while their prerequisites remain satisfied. Key Vault imports and manually uploaded certificates have different renewal paths.';
  if (question === 'binding' && gapIsCovered('binding', registry)) return 'Check the certificate bound to the custom domain. A replacement certificate and the domain’s active TLS binding are separate things to verify.';
  if (question === 'code' && gapIsCovered('code', registry)) return 'Check how the application loads its certificate. Renewal can change the thumbprint, so explicit certificate references may need updating.';
  return '';
}
