<template>
  <figure class="gallery-film" :class="{'is-dark':isDark,'is-unframed':unframed}">
    <div class="gallery-film-frame">
      <video ref="video" class="gallery-film-video" :src="started ? source : undefined" :poster="poster" :controls="started && controlsVisible" :aria-hidden="!started" :tabindex="started ? 0 : -1" :preload="started ? 'metadata' : 'none'" playsinline aria-label="The View Gallery introduction" @play="onPlay" @pause="onPause" @ended="onEnded" @loadedmetadata="restorePlayback" @error="onError" />
      <button v-if="!started" ref="playButton" class="gallery-film-play" type="button" aria-label="Play The View Gallery introduction, 1 minute 39 seconds" @click="play">
        <span class="gallery-film-poster" aria-hidden="true">
          <img class="gallery-film-poster-model" :src="poster" alt="" draggable="false" />
          <span class="gallery-film-poster-heading"><span class="gallery-film-poster-title"><GalleryMark />The View Gallery</span><span class="gallery-film-poster-project">Part of the project <span>AI × Self</span></span></span>
          <span class="gallery-film-poster-url">henryw.me</span>
          <span class="gallery-film-poster-credit">Music · Solace by Scott Buckley · CC BY 4.0</span>
        </span>
        <span class="gallery-film-play-label">
        <span class="gallery-film-play-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 6 9 6-9 6Z"/></svg></span>
        <span>Watch video<small>1 min 39 sec</small></span>
        </span>
      </button>
    </div>
    <figcaption v-if="failed" class="gallery-film-footer" role="status">
      The video could not play. <a :href="source" target="_blank" rel="noopener">Open the video</a>
    </figcaption>
  </figure>
</template>

<script>
import { initialExhibitionDarkMode } from '../../utils/exhibitionTheme';
import GalleryMark from '../view/GalleryMark.vue';
import { watchVideoControls } from '../../../public/slidepoise/docs/site/video-controls.mjs';
const mediaBase = '/assets/video/view-gallery/';

export default {
  name: 'GalleryFilm',
  components: { GalleryMark },
  props: { active: { type: Boolean, default: true }, dark: { type: Boolean, default: null }, unframed: { type: Boolean, default: false } },
  data: () => ({ siteDark: initialExhibitionDarkMode(), started: false, failed: false, controlsVisible: true }),
  computed: {
    isDark() { return this.dark ?? this.siteDark; },
    source() { return `${mediaBase}the-view-gallery${this.isDark ? '-dark' : ''}.mp4`; },
    poster() { return `${mediaBase}poster${this.isDark ? '-dark' : ''}.webp`; },
  },
  watch: {
    active(value) { if (!value) this.pause(); },
    async source() {
      if (!this.started) return;
      const video = this.$refs.video;
      this._resumeState ??= { time: video.currentTime, playing: !video.paused };
      video.pause();
      this.failed = false;
      await this.$nextTick();
      video.load();
      if (this._resumeState?.playing && this.active && !document.hidden) {
        try { await video.play(); }
        catch (error) { if (error.name !== 'AbortError') this.failed = true; }
      }
    },
  },
  mounted() {
    this._controlsCleanup = watchVideoControls(this.$refs.video, visible => { this.controlsVisible = visible; });
    document.addEventListener('visibilitychange', this.visibilityChanged);
    window.addEventListener('view-summary-play', this.otherAudio);
    window.addEventListener('theme-change', this.syncTheme);
    this._observer = new IntersectionObserver(([entry]) => {
      if (!entry.isIntersecting && !document.fullscreenElement && !this.$refs.video?.webkitDisplayingFullscreen) this.pause();
    });
    this._observer.observe(this.$el);
  },
  beforeUnmount() {
    this._controlsCleanup?.();
    this.pause();
    this._observer?.disconnect();
    document.removeEventListener('visibilitychange', this.visibilityChanged);
    window.removeEventListener('view-summary-play', this.otherAudio);
    window.removeEventListener('theme-change', this.syncTheme);
  },
  methods: {
    async play() {
      this.started = true;
      this.failed = false;
      await this.$nextTick();
      if (!this.active) return;
      const video = this.$refs.video;
      video.focus({ preventScroll: true });
      try { await video.play(); }
      catch (error) { if (error.name !== 'AbortError') this.failed = true; }
    },
    onPlay() {
      if (!this.active || document.hidden) { this.pause(); return; }
      this._announcedPlayback = true;
      window.dispatchEvent(new CustomEvent('view-summary-play', { detail: this }));
      document.querySelectorAll('.gallery-film-video').forEach(video => {
        if (video !== this.$refs.video) video.pause();
      });
    },
    onPause() {
      if (!this._announcedPlayback) return;
      this._announcedPlayback = false;
      window.dispatchEvent(new CustomEvent('view-summary-pause', { detail: this }));
    },
    onEnded() { this._resumeState = null; this.onPause(); },
    onError() { this.failed = true; this.onPause(); },
    pause() { if (this._resumeState) this._resumeState.playing = false; this.$refs.video?.pause(); this.onPause(); },
    syncTheme() { this.siteDark = initialExhibitionDarkMode(); },
    async restorePlayback() {
      const state = this._resumeState;
      if (!state) return;
      this._resumeState = null;
      const video = this.$refs.video;
      video.currentTime = Math.min(state.time, Math.max(0, video.duration - .05));
      if (state.playing && this.active && !document.hidden) {
        try { await video.play(); }
        catch (error) { if (error.name !== 'AbortError') this.failed = true; }
      }
    },
    otherAudio(event) { if (event.detail !== this) this.pause(); },
    visibilityChanged() { if (document.hidden) this.pause(); },
  },
};
</script>

